diagrams.source:
flowchart TD
  r[Read target] --> ok{Readable?}
  ok -->|no| f[FAIL with one HIGH: file is readable]
  ok -->|yes| p{"Prior findings: none?"}
  p -->|yes| full[First pass over the whole claim surface]
  p -->|no| s{Snapshot dir exists?}
  s -->|yes| re[Check prior findings plus diffed lines]
  s -->|no| all[Treat every line as changed, add LOW]

flowchart TD
  a["effort_for(agent, executor)"] --> b{"effort has executor.tier_table()?"}
  b -- yes --> r1[Return that Effort]
  b -- no --> c{"effort has native?"}
  c -- yes --> r2[Return the native Effort]
  c -- no --> r3["Return Effort::High"]

flowchart TD
  a[Skill entry] --> b{"path empty?"}
  b -- yes --> x[Drop]
  b -- no --> c{"kind is convention?"}
  c -- yes --> k[Keep]
  c -- no --> d{Agent}
  d -- write-test --> e{"name or kind contains test or spec?"}
  e -- yes --> k
  e -- no --> x
  d -- code-reviewer --> x
  d -- other agents --> k
  k --> f["Keep the first 16, add 'use for' component_type unless the inventory states it"]

flowchart TD
  a[Serialize request as one JSON line] --> b["host_command under the sandbox"]
  b --> c{Process started?}
  c -- no --> e1["Err: Cannot start program"]
  c -- yes --> d[Write stdin, read stdout and stderr]
  d --> t{Done within timeout?}
  t -- no --> e2["Err: took longer than N seconds"]
  t -- yes --> s{Exit status success?}
  s -- no --> e3["Err: exited with status and last stderr line"]
  s -- yes --> z{Output over 64 MB?}
  z -- yes --> e4["Err: answer larger than 64 MB"]
  z -- no --> p["parse_answer"]

flowchart TD
  t[Significant token] --> k{Keyword?}
  k -- yes --> kw["keyword(): def rules, impl blocks, Go and JS forms"]
  k -- no --> n{Name not consumed?}
  n -- no --> skip[No definition]
  n -- yes --> b{Inside Go block?}
  b -- yes --> gd["go_def"]
  b -- no --> f{Family rule}
  f -- Python --> py["py_assign: module variable or class field"]
  f -- Shell --> sh["name() at line start is a function"]
  f -- C --> c["c_function: type name(args) {"]
  f -- other --> m["member(): field, method or enum constant"]

flowchart TD
  a["Candidates: same family, not Module, no tests unless test file"] --> b{Qualifier}
  b -- SelfLike --> c[Own file definitions]
  b -- "Name q" --> d{Container equals q?}
  d -- yes --> e[Own file, else nearest]
  d -- no --> f{Module name equals q?}
  f -- yes --> g[Nearest]
  f -- no --> h{Member?}
  b -- None --> h
  h -- yes --> i["Member kinds whose type the file names; own, else nearest with cap"]
  h -- no --> j{Defined in own file?}
  j -- yes --> k[Own file definitions]
  j -- no --> l["Bare kinds within the family tier limit; nearest with cap"]

flowchart TD
  a["callers(symbol, defined_in, 0)"] --> b{Definitions found?}
  b -- no --> z[Empty impact]
  b -- yes --> c[Frontier: the symbol]
  c --> d["callers(name, file, 5000) per frontier item"]
  d --> e{Import-only or already seen?}
  e -- yes --> d
  e -- no --> f{Total at limit?}
  f -- yes --> t[Mark truncated]
  f -- no --> g[Add to hop; named callers join next frontier]
  g --> h{Hop empty or depth reached?}
  h -- no --> d
  h -- yes --> r[Return hops]

flowchart TD
  a["usages_at(symbol, path, line, col)"] --> b{File and name indexed and readable?}
  b -- no --> n[By-name usages]
  b -- yes --> c{Name token on the line?}
  c -- no --> n
  c -- yes --> d{Token is a definition?}
  d -- yes --> t[Target: that definition]
  d -- no --> m["meaning()"]
  m --> e{Empty and not sure?}
  e -- yes --> n
  e -- no --> f{Empty?}
  f -- yes --> z[Empty usages]
  f -- no --> t
  t --> u["Add implemented interface methods, 8 levels"]
  u --> r["usages_of with meaning filter"]

flowchart TD
  d[ExecutionDelta] --> p{"Policy deny from the guard layer?"}
  p -->|"rule in GUARDS"| g[Guard signal]
  p -->|other| e{"Egress refused and local?"}
  e -->|yes| eg[Egress signal]
  e -->|no| dc{Decoy delta?}
  dc -->|yes| de[Decoy signal]
  dc -->|no| none[No signal]
  g --> rec[Runner appends ContainmentSignal event]
  eg --> rec
  de --> rec
  rec --> cnt{"PAUSE_AFTER signals for this execution?"}
  cnt -->|yes| pause[Session pauses]

flowchart TD
  t["@key/path tag in text"] --> k{"key is _artifacts?"}
  k -->|yes| v{visible_file finds a regular file inside the folder?}
  v -->|yes| add[Add the tag and absolute path]
  v -->|no| skip[Leave the tag as plain text]
  k -->|no| p{key names a workspace project?}
  p -->|no| skip
  p -->|yes| n{normalize accepts the path?}
  n -->|no| skip
  n -->|yes| c{Canonical path is inside the project root?}
  c -->|yes| add
  c -->|no| skip

flowchart TD
  m[Model id] --> s{"provider prefix given?"}
  s -->|yes| h[Put that provider first]
  s -->|no| fp[Use the first-party providers]
  h --> fp
  fp --> ex{Exact id listed?}
  ex -->|yes| r[Use that entry]
  ex -->|no| pre{Listed id plus a dash is a prefix?}
  pre -->|yes| lp[Use the longest such id]
  pre -->|no| any{Any provider lists the exact id?}
  any -->|yes| alpha[Use the first provider in name order]
  any -->|no| none["No price, cost 0"]

flowchart TD
    a{"Stopped?"} -- yes --> f[Fail: The spec stage was stopped.]
    a -- no --> b{"Busy, gate open, or routing?"}
    b -- yes --> w[Wait]
    b -- no --> c{"Failed?"}
    c -- yes --> g[ExecutionFailed gate]
    c -- no --> d{"No spec or needs_run?"}
    d -- yes --> e{"FAILs at limit?"}
    e -- yes --> rg[FactCheckRecurring gate]
    e -- no --> gen[Spawn generate-spec round n]
    d -- no --> q{"Open questions not asked for this version?"}
    q -- yes --> qg[OpenQuestions gate]
    q -- no --> fc{"Fact-check of current version?"}
    fc -- none --> chk[Spawn fact-check]
    fc -- FAIL --> w
    fc -- PASS --> ap["Done, or SpecApproval gate"]

flowchart TD
    p[Idle phase] --> rm{"Depends on a blocked or removed phase?"}
    rm -- yes --> r[Removed from the queue]
    rm -- no --> busy{"Another implement loop active in its project?"}
    busy -- yes --> w[Wait]
    busy -- no --> deps{"Every dependency passed review?"}
    deps -- no --> w
    deps -- yes --> go[Spawn the work agent with WorkKind Initial]

flowchart TD
    a{"Valid review submit?"} -- no --> f[Failed]
    a -- yes --> b{"security_block or a BLOCKER finding?"}
    b -- yes --> bf["Work BlockerFix, blocker_open set"]
    b -- no --> c{"Any auto-fixable finding?"}
    c -- yes --> af["Autofix, then failed HIGH or MEDIUM fixes rejoin"]
    c -- no --> d{"HIGH or MEDIUM remaining?"}
    af --> d
    d -- none --> s["Stage, or Done when staging is off"]
    d -- some --> e{"iterations at cap?"}
    e -- no --> fx[Work Fix with fix_instructions]
    e -- yes --> cap["CapReached, or Resolve under YOLO"]

flowchart TD
    a{"Code done and a phase passed?"} -- no --> w[Skip project]
    a -- yes --> f{"Format ran?"}
    f -- no --> fc[Command Format]
    f -- yes --> c{"Closing choice known?"}
    c -- no --> g["Batched ClosingGate, or both on when requested"]
    c -- yes --> t{"Tests chosen?"}
    t -- yes --> ts["EPA in parallel, then write-test serially"]
    t -- no --> d{"Docs chosen?"}
    ts --> d
    d -- yes --> ds["Documentation writer, at most 4 at once"]
    d -- no --> e[Done]
    ds --> b["Architecture when 2 or more parts, then WriteBook"]

flowchart TD
    a[Resolve judge route and prompt] --> b["Services::judge attempt n of 3"]
    b --> c{"Call ok and output validates?"}
    c -- yes --> d[Append DecisionMade]
    c -- no --> e["Sleep 500 ms times n"]
    e --> f{"Attempts left?"}
    f -- yes --> b
    f -- no --> g{"Completion judge?"}
    g -- yes --> h[Fallback report from the session state]
    g -- no --> i[SessionFailed with provider hint]

flowchart TD
tick["Wait: live change, 500 ms, exit, or cancel"] --> exited{"Cancelled or CLI exited?"}
exited -- yes --> endA["Return Cancelled, Submitted, or Exited"]
exited -- no --> submit{"Submit recorded?"}
submit -- yes --> turn{"Stop after submit, agy quiet 4 s, or 20 s passed?"}
turn -- yes --> endS[Return Submitted]
turn -- no --> tick
submit -- no --> waiting{"Waiting on a subagent?"}
waiting -- yes --> wakeN["wait_for_wake, then type the note"]
wakeN --> tick
waiting -- no --> gave{"Gave up or past deadline?"}
gave -- yes --> endG["Return GaveUp or Timeout"]
gave -- no --> startup["Startup screen checks"]
startup --> idle{"Quiet for idle_nudge?"}
idle -- "yes, 2 nudges used" --> endI[Return Idle]
idle -- "yes, fewer used" --> nudge["Type live nudge text"]
nudge --> tick
idle -- no --> tick

flowchart TD
p[parse_hook_args] -->|error| x1["stderr, exit 1"]
p --> e{"Execution id known?"}
e -- no --> x0["No output, exit 0"]
e -- yes --> u{"OSTRA_URL and OSTRA_TOKEN set?"}
u -- no --> fc[fail_closed]
u -- yes --> post["POST /internal/policy"]
post --> ok{"2xx with a readable PolicyResponse?"}
ok -- yes --> pr["Print stdout, exit with exit_code"]
ok -- no --> fc
fc --> pre{PreToolUse?}
pre -- yes --> deny["Print the adapter's deny, exit 0"]
pre -- no --> quiet[Exit 0]

flowchart TD
s[Stop event] --> i{"Inspect or waiting?"}
i -- yes --> a1[Allow]
i -- no --> sub{"Submit recorded?"}
sub -- yes --> a2["Allow, set stopped_after_submit"]
sub -- no --> n{"stops_without_submit below 2?"}
n -- yes --> b["Block with the reply or submit instruction"]
n -- no --> g["Allow, set gave_up"]

flowchart TD
    resp[Record the response] --> stop{Stop reason}
    stop -->|PauseTurn| next[Next turn, no new user message]
    stop -->|Refusal| refused["Fail: The model refused to continue"]
    stop -->|"MaxTokens, no tool calls"| cont{"continues >= 3?"}
    cont -->|yes| limit["Fail: kept hitting its output limit"]
    cont -->|no| more[Add continue message, next turn]
    stop -->|other| tools{Any tool calls?}
    tools -->|no| rem{Already reminded?}
    rem -->|yes| ok["Return Ok, no submit, final_text"]
    rem -->|no| remind[Add submit or reply reminder, next turn]
    tools -->|yes| run[run_tools]

flowchart TD
    call[Next tool call] --> sub{Name is submit_agent?}
    sub -->|yes| val{submit accepted?}
    val -->|yes| endsub["Fill Not run results, return Submitted"]
    val -->|no| errres[Store error result, next call]
    sub -->|no| conc{is_concurrent?}
    conc -->|yes| group["join_all over adjacent concurrent calls"]
    conc -->|no| coord{is_coord_tool?}
    coord -->|yes| runend{RunEnd}
    runend -->|Continue| call
    runend -->|"Wait or Finish"| endco["Fill Not run results, return Submitted with end_payload"]
    coord -->|no| single[Run the call alone]
    group --> call
    single --> call

flowchart TD
    start[submit_agent call] --> json{"__invalid_json present?"}
    json -->|yes| err[Error tool result, run continues]
    json -->|no| pol{Policy Deny?}
    pol -->|yes| err
    pol -->|no| val{validate_submit ok?}
    val -->|no| err
    val -->|yes| doc{doc::check_submit ok?}
    doc -->|no| err
    doc -->|yes| status[Map status field]
    status --> rep{"Ok, report_file set and missing, not CodeReviewer?"}
    rep -->|yes| err
    rep -->|no| ok["Result received. Run ends"]

flowchart TD
    msg[Incoming message] --> resp{"is_response: no method, has result or error?"}
    resp -->|yes| match[Transport matches it to a pending id]
    resp -->|no| hasid{"Has id?"}
    hasid -->|yes| ping{"method is ping?"}
    ping -->|yes| empty[Reply with empty result]
    ping -->|no| unsup["Reply with error -32601"]
    hasid -->|no| lc{"notifications/tools/list_changed?"}
    lc -->|yes| flag[Set tools_changed]
    lc -->|no| drop[Ignore]

flowchart TD
    a[Redirect attempt] --> n{"More than 5 previous URLs?"}
    n -->|yes| err["Error: too many redirects"]
    n -->|no| s{"Same scheme, host and port as the first URL?"}
    s -->|yes| f[Follow]
    s -->|no| st["Stop, return the redirect response"]

flowchart TD
    u[URL] --> p{"Parses as a URL?"}
    p -->|no| e1["Err: is not a URL"]
    p -->|yes| s{Scheme}
    s -->|https| h{"Has a host?"}
    h -->|yes| ok[Ok]
    h -->|no| e2["Err: must use https"]
    s -->|http| l{"Loopback host, or same origin as the MCP server?"}
    l -->|yes| ok
    l -->|no| e2
    s -->|other| e2

flowchart TD
    start[request.send] --> ok{Response received?}
    ok -- no --> neterr["Failed { status: None, message: error text }"]
    ok -- yes --> s2xx{Status 200 to 299?}
    s2xx -- yes --> delivered[Delivered]
    s2xx -- no --> gone{Status 404 or 410?}
    gone -- yes --> g[Gone]
    gone -- no --> warn["tracing::warn push service refused a message"]
    warn --> failed["Failed { status: Some, message: first 500 chars of body }"]

flowchart TD
    A{"answer_only run and the call writes?"}
    A -->|yes| D1[Deny answer-only]
    A -->|no| R{"tool is Report?"}
    R -->|yes| RL["Deny lesson-gate if a lesson is pending and reason is empty, else pass"]
    R -->|no| DOC{"tool is Document?"}
    DOC -->|yes| CD[check_document]
    DOC -->|no| MG{"ProjectList or ProjectCreate?"}
    MG -->|yes| CM[check_manage]
    MG -->|no| SB{"tool name starts with submit_?"}
    SB -->|yes| SBC["Deny reply-first if owes_reply, lesson-gate if status ok and a lesson is pending"]
    SB -->|no| OS["PowerShell or Cmd: check_opaque_shell"]
    OS --> WP["check_write for each write path"]
    WP --> RP["check_windows_path and check_read on the read path"]
    RP --> SH["Bash: check_shell, check_shell_reads, target checks, build-streak gate"]

flowchart TD
    T[Resolved write target] --> C1{"run creates a project and target is outside session dir and temp?"}
    C1 -->|yes| MT[Deny manage-tools]
    C1 -->|no| C2{"Windows stream, device, UNC, or drive-relative form?"}
    C2 -->|yes| WP[Deny windows-path]
    C2 -->|no| C3{"strict and target is protected?"}
    C3 -->|yes| SP[Deny self-protection]
    C3 -->|no| C4{"inside workspace artifacts or books dir?"}
    C4 -->|yes| WA["Deny workspace-artifacts or workspace-docs"]
    C4 -->|no| C5{"path has a .git component?"}
    C5 -->|yes| GM[Deny git-metadata]
    C5 -->|no| C6{"engine state, tool-owned, or another role's file?"}
    C6 -->|yes| SO[Deny state-ownership]
    C6 -->|no| NEXT[Continue to part 2]

flowchart TD
    N[Target passed part 1] --> A1{"inside a factcheck-snapshot- dir?"}
    A1 -->|yes| S1[check_scope]
    A1 -->|no| A2{"spec, plan, or research name and agent is not the owner?"}
    A2 -->|yes| AO[Deny artifact-ownership]
    A2 -->|no| A3{"session file rendered from a typed document?"}
    A3 -->|yes| DT[Deny document-tool]
    A3 -->|no| S1
    S1 -->|refuses| SC["Deny no-tests-from-implementer or write-scope"]
    S1 -->|passes| R1{"report declared, target in session root, name starts with ostra-, not own agent file?"}
    R1 -->|no| OK[Pass layer 1]
    R1 -->|yes| R2{"target equals declared report?"}
    R2 -->|differs and strict| RP[Deny report-path]
    R2 -->|differs and not strict| OK
    R2 -->|yes| R3{"lesson pending?"}
    R3 -->|yes| LG[Deny lesson-gate]

flowchart TD
    A{"implementer, outside session, test path in repo?"}
    A -->|yes| NT[Deny no-tests-from-implementer]
    A -->|no| B{"strict?"}
    B -->|no| OK[Pass]
    B -->|yes| C{"agent is quick-answer?"}
    C -->|yes| WS[Deny write-scope]
    C -->|no| D{"in session dir or session root?"}
    D -->|yes| OK
    D -->|no| E{"in repo?"}
    E -->|no| F{"session-only agent and in temp?"}
    F -->|yes| OK
    F -->|no| WS
    E -->|yes| G{"initializer?"}
    G -->|yes| H{"inside .agents/skills or the project runtime dir, and not only the legacy skills dir?"}
    H -->|yes| OK
    H -->|no| WS
    G -->|no| J{"session-only agent?"}
    J -->|yes| WS
    J -->|no| OK

flowchart TD
    A{"any simple command matches a deny rule?"}
    A -->|yes| D[Deny naming the rule]
    A -->|no| B{"any matches an ask rule?"}
    B -->|yes| K[Ask naming the rule]
    B -->|no| C{"unmodelled statement or incomplete parse?"}
    C -->|yes| M["by mode: bypass allows, plan denies, else Ask unmodelled or unparsed"]
    C -->|no| L[For each simple command]
    L --> E{"static name matches an allow or session rule?"}
    E -->|yes| NX[Next command]
    E -->|no| F{"read-only, git inside repo, targets known and in session or temp?"}
    F -->|yes| NX
    F -->|no| G{"acceptEdits and mkdir, touch, cp, mv or read-only, targets in repo, session, or temp?"}
    G -->|yes| NX
    G -->|no| H{"mode"}
    H -->|bypass| NX
    H -->|plan| D2["Deny mode:plan"]
    H -->|default or acceptEdits| K2["Ask mode:default or mode:acceptEdits"]
    NX --> Z["after the last command: Allow with the last rule, read-only, or mode:bypass"]

flowchart TD
    T[Each write target] --> R{"deny or ask rule matches?"}
    R -->|deny| D[Return Deny]
    R -->|ask| A[Remember Ask]
    R -->|no| C{"file runs code later?"}
    C -->|yes| M["mode_default: bypass allows, plan denies, else Ask"]
    C -->|no| S{"in session dir or temp?"}
    S -->|yes| N[Next target]
    S -->|no| AL{"allow rule matches?"}
    AL -->|yes| N
    AL -->|no| AE{"acceptEdits and in repo?"}
    AE -->|yes| N
    AE -->|no| M
    N --> F["after all targets: Ask if any asked, else Allow naming the rule"]

flowchart TD
    O[Bash build or test outcome] --> F{"failed_from result"}
    F -->|None| X[No change]
    F -->|false| P{"consecutive at least 3 and a signature known?"}
    P -->|yes| RC["push Recovery, note asks for a lesson"]
    P -->|no| RS["reset consecutive to 0"]
    RC --> RS
    F -->|true| INC["consecutive += 1, keep signature"]
    INC --> T2{"count at least 2?"}
    T2 -->|no| Q[No note]
    T2 -->|yes| RL["recall query = signature"]
    RL --> T3{"count 3 or 4?"}
    T3 -->|yes| W[warning note]
    T3 -->|no| T5{"count at least 5?"}
    T5 -->|yes| B["stuck note, build commands blocked"]

flowchart TD
    a{"api_key_env value set?"} -->|yes| r1["ApiKey::new, source env:NAME"]
    a -->|no| b{"auth_token_env value set?"}
    b -->|yes| r2["ApiKey::bearer, source env:NAME"]
    b -->|no| c{"saved api_key?"}
    c -->|yes| r3["ApiKey::new, source saved"]
    c -->|no| d{"saved auth_token?"}
    d -->|yes| r4["ApiKey::bearer, source saved"]
    d -->|no| e{"keychain_service set and entry readable?"}
    e -->|yes| r5["ApiKey::new, source keychain"]
    e -->|no| r6[None]

flowchart TD
    s["split_once on colon"] --> ok{"both sides non-empty?"}
    ok -->|no| bad["Err BadModel"]
    ok -->|yes| g{"get(name) found?"}
    g -->|yes| r["Ok provider and model"]
    g -->|no| k{"name is anthropic or openai?"}
    k -->|yes| nk["Err NoKey"]
    k -->|no| up["Err UnknownProvider"]

flowchart TD
    a["select: cancel.cancelled or attempt"] --> c{"cancelled?"}
    c -->|yes| x["Err Cancelled"]
    c -->|no| r{"result"}
    r -->|Ok| ok[Return Ok]
    r -->|Err| rt{"is_retryable?"}
    rt -->|no| e[Return error]
    rt -->|yes| s{"started?"}
    s -->|yes| st["Err Stream"]
    s -->|no| n{"n below max_retries?"}
    n -->|no| e
    n -->|yes| w["sleep delay, cancellable"]
    w --> a

flowchart TD
  start["decide(cfg)"] --> off{"mode is Off?"}
  off -->|yes| u0["Unsandboxed(None)"]
  off -->|no| probe{"backend() is Some?"}
  probe -->|yes| s["Sandboxed(backend)"]
  probe -->|no| auto{"mode is Auto?"}
  auto -->|yes| u1["Unsandboxed(Some(unavailable_message))"]
  auto -->|Required| err["Err: sandbox required but not available"]

flowchart TD
  m[ReadOnly rule] --> h{"nearest mounted ancestor is Hidden and rule not revealed?"}
  h -->|yes| drop[Drop the rule]
  h -->|no| ex{"path exists?"}
  ex -->|yes| keep["Keep as --ro-bind"]
  ex -->|no| w{"nearest ancestor is a Writable bind onto itself?"}
  w -->|yes| ph["Create placeholder and keep"]
  w -->|no| drop2["Drop, nothing can create it"]

flowchart TD
  a{"arch equals ARCH?"} -->|no| kill[KILL_PROCESS]
  a -->|yes| x{"x86_64 and x32 bit set?"}
  x -->|yes| e1[ENOSYS]
  x -->|no| r{"call in REFUSED?"}
  r -->|yes| p1[EPERM]
  r -->|no| m{"call in MISSING?"}
  m -->|yes| e2[ENOSYS]
  m -->|no| u{"unshare or clone with CLONE_NEWUSER?"}
  u -->|yes| p2[EPERM]
  u -->|no| i{"ioctl TIOCSTI or TIOCLINUX?"}
  i -->|yes| p3[EPERM]
  i -->|no| allow[ALLOW]

flowchart TD
  a[check_cookie value] --> b{"Cached and checked under 5 s ago?"}
  b -- yes --> c[Valid while expiry is in the future]
  b -- no --> d[Read auth:cookie:hash from registry]
  d --> e{"Record exists and not expired?"}
  e -- no --> f["Delete expired row, drop cache entry, refuse"]
  e -- yes --> g{"Legacy or last_seen 60 s old?"}
  g -- yes --> h[kv_replace with new last_seen]
  g -- no --> i["Cache expiry and time, accept"]
  h --> i

flowchart TD
  a[Request] --> b{"Host allowed?"}
  b -- no --> r421[421 This host is not allowed]
  b -- yes --> c{"Private name set and path not /internal/?"}
  c -- "yes, API" --> r421b[421 Open Ostra at the private name]
  c -- "yes, page" --> r307["307 to http://private/path?query"]
  c -- no --> d{"/internal/ from non-local peer or with Origin or Sec-Fetch-Site?"}
  d -- yes --> r403[403]
  d -- no --> e{"API path?"}
  e -- no --> ok[Route or static file]
  e -- yes --> f{"Origin, Sec-Fetch-Site, Sec-Fetch-Dest allowed?"}
  f -- no --> r403b[403 This origin is not allowed]
  f -- yes --> g{"exchange path or valid cookie?"}
  g -- no --> r401[401 Sign in with the URL]
  g -- yes --> ok

flowchart TD
  a[Path] --> b{"Embedded file exists?"}
  b -- yes --> f[Serve with MIME and cache header]
  b -- no --> c{"api/, internal/, assets/, or root file with a dot, not .html?"}
  c -- yes --> n[404]
  c -- no --> i[Serve index.html]

flowchart TD
  a[PreToolUse call] --> b{"Running record?"}
  b -- no --> d1[Deny self-protection]
  b -- yes --> c{"Gateway or management tool, not inspect?"}
  c -- yes --> al["Allow unchecked, MCP handler checks"]
  c -- no --> e{"Inspect run?"}
  e -- yes --> d2[Deny read-only-session]
  e -- no --> f[ExecutionPolicy::check]
  f --> g[Log ToolCall and Policy unless served_by_mcp]

flowchart TD
  a["ready(root, cfg, force)"] --> b[conn by fingerprint]
  b --> c{"force?"}
  c -- yes --> r[Reset Inner]
  c -- no --> d{"Live client?"}
  r --> d
  d -- yes --> e{"List older than 30 s or tools changed?"}
  e -- no --> ok[Return client and tools]
  e -- yes --> l[list_tools] --> ok
  d -- no --> f{"Error under 20 s old?"}
  f -- yes --> err[Return cached error]
  f -- no --> g["Approved config, endpoint, Client::connect, list_tools"]
  g --> h[Store client or error]

flowchart TD
  a["set_hidden(path, hidden)"] --> b{"Artifact exists?"}
  b -- no --> n[404]
  b -- yes --> c{"hidden?"}
